def build(md, files=None, config='[book]\ntitle="T"\n[output.markdown]\n'):
    root=pathlib.Path("/tmp/ltest")
    if root.exists(): shutil.rmtree(root)
    (root/"src").mkdir(parents=True); (root/"book.toml").write_text(config)
    (root/"src"/"SUMMARY.md").write_text("- [C](c.md)\n- [Sub](sub/d.md)\n")
    (root/"src"/"sub").mkdir(exist_ok=True); (root/"src"/"sub"/"d.md").write_text("# D\n")
    (root/"src"/"c.md").write_text(md)
    if files:
        for k,v in files.items():
            p=root/"src"/k; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(v)
    r=subprocess.run([REF,"build",str(root)],capture_output=True,text=True)
    out=""
    if (root/"book"/"c.md").exists(): out=(root/"book"/"c.md").read_text()
    else: 
        # single markdown destination root/book
        pass
    print("exit",r.returncode); print("stderr",r.stderr); print("OUTPUT:\n"+out)
    return out
