import os, sys, re, math, datetime, html

VERSION = "0.5.0-alpha.1"

LEVELS = {"off":0,"error":1,"warn":2,"info":3,"debug":4,"trace":5}
LEVEL_NAMES = {1:"ERROR",2:"WARN",3:"INFO",4:"DEBUG",5:"TRACE"}

class _Logger:
    def __init__(self):
        self._parse()
    def _parse(self):
        raw = os.environ.get("RUST_LOG")
        self.global_level = LEVELS["info"]
        self.target_rules = []  # list (prefix, level)
        if raw is None or raw == "":
            return
        self.global_level = LEVELS["error"] if any("=" in p for p in raw.split(",")) else None
        # env_logger-ish handling
        has_target=False
        global_set=None
        rules=[]
        for part in raw.split(","):
            part=part.strip()
            if not part: continue
            if "=" in part:
                tgt, lvl = part.split("=",1)
                lvl_l=lvl.strip().lower()
                if lvl_l in LEVELS:
                    rules.append((tgt.strip(), LEVELS[lvl_l])); has_target=True
                else:
                    # invalid level maybe target with max
                    rules.append((tgt.strip(), LEVELS["trace"])); has_target=True
            elif part.lower() in LEVELS:
                global_set=LEVELS[part.lower()]
            else:
                rules.append((part, LEVELS["trace"])); has_target=True
        self.target_rules=rules
        if global_set is not None:
            self.global_level=global_set
        elif has_target:
            self.global_level=0
        else:
            self.global_level=LEVELS["info"]
    def enabled(self, level, target):
        # most specific (longest) matching prefix rule
        best_len=-1; best=None
        for prefix,lvl in self.target_rules:
            if target==prefix or target.startswith(prefix):
                if len(prefix)>best_len:
                    best_len=len(prefix); best=lvl
        allowed = best if best is not None else self.global_level
        return level <= (allowed or 0)
    def log(self, level, target, message):
        if not self.enabled(level,target): return
        ts=datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        # message may contain newlines; prefix only first line (env_logger behaviour)
        sys.stderr.write(f"{ts} [{LEVEL_NAMES[level]}] ({target}): {message}\n")
        sys.stderr.flush()
    def error(self,target,msg): self.log(1,target,msg)
    def warn(self,target,msg): self.log(2,target,msg)
    def info(self,target,msg): self.log(3,target,msg)
    def debug(self,target,msg): self.log(4,target,msg)
    def trace(self,target,msg): self.log(5,target,msg)

log=_Logger()

def reinit_log():
    global log
    log=_Logger()
    return log

class MdError(Exception):
    """Error with an anyhow-like chain. causes is a list of strings."""
    def __init__(self, message, causes=None):
        super().__init__(message)
        self.message=str(message)
        self.causes=[]
        if causes:
            for c in causes:
                if isinstance(c,MdError):
                    self.causes.append(c.message); self.causes.extend(c.causes)
                else:
                    self.causes.append(str(c))
    def chain(self):
        return [self.message]+self.causes

