    if isinstance(e, UnicodeDecodeError) or getattr(e,"_mdbook_utf8_stream",False):
        return "stream did not contain valid UTF-8"
    if isinstance(e,OSError):
        msg=os.strerror(e.errno) if e.errno else str(e)
