        if len(causes)==1:
            for line in causes[0].split("\n"):
                out += "    "+line+"\n"
            out=out.rstrip("\n") if not causes[0].endswith("\n") else out
            # anyhow indents; a trailing blank handled by caller log newline
            if causes[0].endswith("\n"):
                pass
