    """Rust Path::with_extension."""
    p=str(p)
    # directory part (including trailing slash handling)
    p2=p.rstrip("/")
    idx=p2.rfind("/")
    if idx>=0:
        dirpart=p2[:idx+1]; name=p2[idx+1:]
    else:
        dirpart=""; name=p2
    if name in ("",".",".."):
        return p
    stem,old = file_stem_ext(name)
    return f"{dirpart}{stem}.{ext}"

def url_from_path(p):
    """Convert a path string to a URL-ish path dropping CurDir components."""
    absolute,parts=path_components(p)
    out="/".join(parts)
    return "/"+out if absolute else out

def html_url_path(md_path):
    return url_from_path(with_extension(md_path,"html"))

def path_to_root_for(html_rel_url):
    """'../' repeated for each directory component of an output file."""
    absolute,parts=path_components(html_rel_url)
    if len(parts)<=1:
        return ""
    return "../"*(len(parts)-1)

# ---------- escaping ----------

def escape_html_text(s):
    return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")

def escape_html_attr(s):
    return (str(s).replace("&","&amp;").replace("<","&lt;")
            .replace(">","&gt;").replace('"',"&quot;"))

def escape_handlebars(s):
    return (str(s).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
            .replace('"',"&quot;").replace("'","&#x27;")
            .replace("`","&#x60;").replace("=","&#x3D;"))

def escape_toc_text(s):
    return (str(s).replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
            .replace('"',"&quot;").replace("'","&#39;"))

def rust_debug_str(s):
    out='"'
    for ch in str(s):
        o=ord(ch)
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\n': out+='\\n'
        elif ch=='\r': out+='\\r'
        elif ch=='\t': out+='\\t'
        elif o<0x20 or o==0x7f: out+=f'\\u{{{o:x}}}'
