    """Read like Rust fs::read_to_string: raises OSError, or an OSError whose
    display should be 'stream did not contain valid UTF-8'."""
    with open(path,'rb') as f:
        data=f.read()
    try:
        return data.decode('utf-8')
    except UnicodeDecodeError as e:
        err=OSError("stream did not contain valid UTF-8")
        err._mdbook_utf8_stream=True
        raise err

