        ln = (e.end-e.start) if e.end>e.start else 1
        return f"invalid utf-8 sequence of {ln} bytes from index {e.start}"

def human_size(n):
    if n<1024:
        return f"{n}B"
    units=["KiB","MiB","GiB","TiB","PiB","EiB"]
    val=float(n)
    for u in units:
        val/=1024.0
        if val<1024.0 or u==units[-1]:
            return f"{val:.2f}{u}"
    return f"{val:.2f}EiB"
