import re, datetime

class TomlDatetime(str):
    pass

class TomlError(Exception):
    def __init__(self, message, line, col, line_text):
        self.message=message; self.line=line; self.col=col; self.line_text=line_text
    def render(self):
        width=len(str(self.line))
        gutter=" "*(width+1)
        return (f"TOML parse error at line {self.line}, column {self.col}\n"
                f"{gutter}|\n"
                f"{self.line} | {self.line_text}\n"
                f"{gutter}| {' '*(self.col-1)}^\n"
                f"{self.message}\n")

class Parser:
    def __init__(self,text):
        self.s=text
        self.n=len(text)
        self.i=0
        self.lines=text.split("\n")
    def pos(self, idx=None):
        if idx is None: idx=self.i
        before=self.s[:idx]
        line=before.count("\n")+1
        last=before.rfind("\n")
        col=idx-last if last>=0 else idx+1
        # line/col as toml crate: col is 1-based char column; for very first
        # line with error at first char it reports 1. above gives idx+1 there.
        lt=self.lines[line-1] if line-1 < len(self.lines) else ""
        return line,col,lt
    def err(self,message,idx=None):
        line,col,lt=self.pos(idx)
        raise TomlError(message,line,col,lt)
    def peek(self):
        return self.s[self.i] if self.i<self.n else ""
    def skip_ws(self, allow_newline=False, allow_comments=False):
        while self.i<self.n:
            c=self.s[self.i]
            if c in " \t":
                self.i+=1
            elif allow_comments and c=="#":
                while self.i<self.n and self.s[self.i]!="\n": self.i+=1
            elif allow_newline and c in "\n\r":
                self.i+=1
            else:
                break
    def expect_eof_or_newline(self):
        self.skip_ws(False)
