            while self.i<self.n and self.s[self.i]!="\n": self.i+=1
        if self.i<self.n and self.s[self.i] not in "\n\r":
            self.err("unexpected key or value, expected newline, `#`")
        # consume newline
        if self.i<self.n and self.s[self.i]=="\r": self.i+=1
        if self.i<self.n and self.s[self.i]=="\n": self.i+=1

