    def parse_bare_key(self):
        m=re.match(r'[A-Za-z0-9_-]+', self.s[self.i:])
        if not m: self.err("expected a table key, found a right bracket" if self.peek()=="]" else "expected an equals, found an identifier")
        self.i+=len(m.group(0)); return m.group(0)
    def parse_key(self):
        self.skip_ws(False)
        parts=[]
        while True:
            self.skip_ws(False)
            c=self.peek()
            if c=='"':
                parts.append(self.parse_basic_string())
            elif c=="'":
                parts.append(self.parse_literal_string())
            else:
                parts.append(self.parse_bare_key())
            self.skip_ws(False)
            if self.peek()==".":
                self.i+=1; continue
