    @property
    def build(self):
        if self._build is None:
            try: self._build=parse_build_cfg(self.raw.get("build"))
            except Exception: self._build=BuildCfg()
        return self._build
    @property
    def rust(self):
        if self._rust is None:
            try: self._rust=parse_rust_cfg(self.raw.get("rust"))
            except Exception: self._rust=RustCfg()
        return self._rust
    def html_config(self):
        """Logs an error and returns defaults on failure (like upstream)."""
        try:
            return parse_html_cfg(self.raw.get("output",{}).get("html") if isinstance(self.raw.get("output"),dict) else None)
        except SerdeErr as e:
            from .util import log_error
            log_error(MdError("Parsing configuration [output.html]",["Couldn't deserialize the value",str(e).rstrip("\n")+"\n"]))
            return HtmlCfg()
        except Exception as e:
            from .util import log_error
            log_error(MdError("Parsing configuration [output.html]",["Couldn't deserialize the value",str(e)]))
            return HtmlCfg()
    def source_dir(self):
        return path_join(self.root,self.book.src)
    def build_dir_abs(self):
        bd=self.build.build_dir
        return bd if os.path.isabs(bd) else path_join(self.root,bd)
    def output_table(self):
        v=self.raw.get("output")
        if v is None: return {}
        if not isinstance(v,dict) or any(not isinstance(x,dict) for x in v.values()):
            raise MdError("failed to get output table config: Couldn't deserialize the value")
        return v
    def preprocessor_table(self):
        v=self.raw.get("preprocessor")
        if v is None: return {}
        if not isinstance(v,dict) or any(not isinstance(x,dict) for x in v.values()):
            raise MdError("failed to get preprocessor table config: Couldn't deserialize the value")
        return v
    def renderer_names(self):
        out=self.output_table()
        if not out: return ["html"]
        return list(out.keys())
    def dest_for_renderer(self,name,dest_override=None):
        base=dest_override if dest_override is not None else self.build_dir_abs()
        names=self.renderer_names()
        if len(names)>1:
            return path_join(base,name)
        return base
    def serialize(self):
        """Config JSON representation for preprocessors/backends."""
        obj={}
        b=self.book
        bookd={"authors":list(b.authors),"language":b.language,"src":b.src}
        if b.title is not None: bookd["title"]=b.title
        if b.description is not None: bookd["description"]=b.description
        if b.text_direction is not None: bookd["text-direction"]=b.text_direction
        obj["book"]=bookd
        build=self.build
        if not build.is_default():
            obj["build"]={"build-dir":build.build_dir,"create-missing":build.create_missing,
                           "extra-watch-dirs":list(build.extra_watch_dirs),"use-default-preprocessors":build.use_default_preprocessors}
        # preprocessor/output raw
        try:
            pre=self.preprocessor_table()
            if pre: obj["preprocessor"]=copy.deepcopy(pre)
        except MdError:
            if isinstance(self.raw.get("preprocessor"),dict): obj["preprocessor"]=copy.deepcopy(self.raw.get("preprocessor"))
        try:
            out=self.output_table()
            if out: obj["output"]=copy.deepcopy(out)
        except MdError:
            if isinstance(self.raw.get("output"),dict): obj["output"]=copy.deepcopy(self.raw.get("output"))
        r=self.rust
        if r.edition is not None:
            obj["rust"]={"edition":r.edition}
        # unknown top-level preserved
        for k,v in self.raw.items():
            if k not in KNOWN_TOP:
                obj[k]=copy.deepcopy(v)
        return sort_keys(obj)

def sort_keys(v):
    if isinstance(v,dict):
        return {k:sort_keys(v[k]) for k in sorted(v.keys(),key=lambda x:str(x))}
    if isinstance(v,list): return [sort_keys(x) for x in v]
    if isinstance(v,TomlDatetime): return {"$__toml_private_datetime":str(v)}
    if isinstance(v,float) and (v!=v or v in (float('inf'),float('-inf'))): return None
    return v

def apply_env(raw):
    for env_key in list(os.environ.keys()):
        if not env_key.startswith("MDBOOK_"): continue
        if env_key=="MDBOOK_": continue
        rest=env_key[len("MDBOOK_"):]
        if not rest: continue
        parts=[]
        for seg in rest.split("__"):
            parts.append(seg.lower().replace("_","-"))
        value_raw=os.environ[env_key]
        try:
            value=json.loads(value_raw)
        except Exception:
            value=value_raw
        # set nested
        cur=raw
        for p in parts[:-1]:
            if not isinstance(cur.get(p),dict):
                cur[p]={}
            cur=cur[p]
        cur[parts[-1]]=value
    return raw

def load_config(root):
    cfg_path=path_join(root,"book.toml")
    raw={}
    if os.path.exists(cfg_path):
        log.debug("mdbook_driver::mdbook",f"Loading config from {cfg_path}")
        try:
            text=read_text_file(cfg_path)
        except OSError as e:
            raise MdError("Couldn't read the file",[os_error_str(e)])
        try:
            raw=parse_toml(text)
        except TomlError as e:
            raise MdError("Invalid configuration file",[e.render().rstrip("\n")])
        # warn unknown top-level (sorted), validate typed sections
        for k in sorted(raw.keys()):
            if k not in KNOWN_TOP:
                log.warn("mdbook_core::config",f'Invalid field "{k}" in book.toml')
        try:
            parse_book_cfg(raw.get("book"))
            parse_rust_cfg(raw.get("rust"))
            parse_build_cfg(raw.get("build"))
        except SerdeErr as e:
            # serde messages end with \n; chain display includes it
            raise MdError("Invalid configuration file",[str(e).rstrip("\n")+"\n"])
        # curly-quotes deprecation warning (emitted when html config is later checked? observed before building)
        # do it in MDBook.build setup via check; here just record
    log.debug("mdbook_core::config","Updating the config from environment variables")
    raw=apply_env(raw)
    cfg=Config(root,raw)
    return cfg

