def serde_type(v):
    if isinstance(v,bool): return f"boolean `{str(v).lower()}`"
    if isinstance(v,int): return f"integer `{v}`"
    if isinstance(v,float): return f"floating point `{v}`"
    if isinstance(v,str): return f'string "{v}"'
    if isinstance(v,list): return "sequence"
    if isinstance(v,dict): return "map"
    if v is None: return "unit value"
    return str(type(v))

class SerdeErr(Exception):
    def __init__(self,msg): self.msg=msg
    def __str__(self): return self.msg

def invalid_type(v,expected,path):
    raise SerdeErr(f"invalid type: {serde_type(v)}, expected {expected}\nin `{path}`\n")

def expect_string(v,path):
    if not isinstance(v,str) or isinstance(v,TomlDatetime): invalid_type(v,"a string",path)
    return v
def expect_bool(v,path):
    if not isinstance(v,bool): invalid_type(v,"a boolean",path)
    return v
def expect_seq(v,path):
    if not isinstance(v,list): invalid_type(v,"a sequence",path)
    return v
def expect_map(v,path,structname=None):
    if not isinstance(v,dict):
        if structname: invalid_type(v,f"struct {structname}",path)
        invalid_type(v,"a map",path)
    return v
def expect_usize(v,path,bits=64):
    if isinstance(v,bool) or not isinstance(v,int): invalid_type(v,"a non-negative integer" if False else "`usize`",path)
    # serde messages for out of range differ; approximate with invalid value
    if v<0 or v>=(1<<bits):
        raise SerdeErr(f"invalid value: integer `{v}`, expected a non-negative integer at most {bits} bits\nin `{path}`\n")
    return v
def expect_u8(v,path):
    if isinstance(v,bool) or not isinstance(v,int): invalid_type(v,"`u8`",path)
    if v<0 or v>255: raise SerdeErr(f"invalid value: integer `{v}`, expected a non-negative integer at most 8 bits\nin `{path}`\n")
    return v

