                        kk=k
                        while kk<end and s[kk]=="`": kk+=1
                        if kk-k==tick: found=(k,kk); break
                        k=kk
                    else: k+=1
                if found:
                    content=s[j:found[0]].replace("\n"," ")
                    if len(content)>=2 and content[0]==" " and content[-1]==" " and content.strip()!="":
                        content=content[1:-1]
                    flush(); nodes.append(Node("code",content)); i=found[1]; continue
                buf.append("`"*tick); i=j; continue
            # autolink / inline html
            if c=="<":
                # autolink scheme
                m=re.match(r'<([A-Za-z][A-Za-z0-9+.-]{1,31}:[^<>\s]*)>',s[i:end])
                if m:
                    flush(); dest=decode_entities(m.group(1),True)
                    nodes.append(Node("link",children=[Node("text",m.group(1))],dest=dest)); i+=len(m.group(0)); continue
                m=re.match(r'<([A-Za-z0-9.!#$%&\'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?)*)>',s[i:end])
                if m:
                    flush(); nodes.append(Node("link",children=[Node("text",m.group(1))],dest="mailto:"+m.group(1))); i+=len(m.group(0)); continue
                htmlnode=self._inline_html(i,end)
                if htmlnode:
                    flush(); nodes.append(Node("html",htmlnode[0])); i=htmlnode[1]; continue
                buf.append("<"); i+=1; continue
            # images / links
            if allow_links and c=="!" and i+1<end and s[i+1]=="[":
                r=self._try_link(i,True,allow_links)
                if r: flush(); nodes.append(r[0]); i=r[1]; continue
                buf.append("!"); i+=1; continue
            if allow_links and c=="[":
                r=self._try_link(i,False,allow_links)
                if r: flush(); nodes.append(r[0]); i=r[1]; continue
                buf.append("["); i+=1; continue
            # emphasis / strikethrough handled by delimiter processing later? inline simple:
            if c in "*_~":
                # count run
                j=i
                while j<end and s[j]==c: j+=1
                run=j-i
                node,nxt=self._try_emphasis(i,j,c,run,end,allow_links)
                if node is not None:
                    flush(); nodes.append(node); i=nxt; continue
                buf.append(c*run); i=j; continue
            # hard break via trailing spaces before newline
            if c=="\n":
                # check buf ends with two spaces
                txt="".join(buf)
                if txt.endswith("  "):
                    buf.clear(); buf.append(txt.rstrip(" "))
                    flush(); nodes.append(Node("hardbreak")); i+=1; continue
                flush(); nodes.append(Node("softbreak")); i+=1; continue
            buf.append(c); i+=1
        flush()
        return nodes
    def _inline_html(self,i_end_holder,end=None):
        s=self.s; i=i_end_holder
        rest=s[i:end]
        # comment
        if rest.startswith("<!--"):
            j=rest.find("-->")
            if j>=0: return rest[:j+3],i+j+3
            return None
        if rest.startswith("<?"):
            j=rest.find("?>")
            if j>=0: return rest[:j+2],i+j+2
            return None
        if rest.startswith("<![CDATA["):
            j=rest.find("]]>")
            if j>=0: return rest[:j+3],i+j+3
            return None
        if rest.startswith("<!") and len(rest)>2 and rest[2].isalpha():
            j=rest.find(">")
            if j>=0: return rest[:j+1],i+j+1
            return None
        m=re.match(r'</?[A-Za-z][A-Za-z0-9-]*(?:\s+[A-Za-z_:][A-Za-z0-9_.:-]*(?:\s*=\s*(?:[^<>\'"\s`=]+|\'[^\']*\'|"[^"]*"))?)*\s*/?>',rest)
        if m: return m.group(0),i+len(m.group(0))
        return None
    def _flanking(self,start,endrun,ch):
        s=self.s
        before=s[start-1] if start>0 else "\n"
        after=s[endrun] if endrun<self.n else "\n"
        before_ws=before.isspace(); before_punct=not before_ws and not before.isalnum()
        after_ws=after.isspace(); after_punct=not after_ws and not after.isalnum()
        left_flanking=not after_ws and (not after_punct or before_ws or before_punct)
        right_flanking=not before_ws and (not before_punct or after_ws or after_punct)
        if ch=="_":
            can_open=left_flanking and (not right_flanking or before_punct)
            can_close=right_flanking and (not left_flanking or after_punct)
        else:
            can_open=left_flanking; can_close=right_flanking
        return can_open,can_close
    def _try_emphasis(self,i,j,ch,run,end,allow_links):
        can_open,_=self._flanking(i,j,ch)
        if not can_open: return None,i
        s=self.s
        # For strikethrough, delimiter must be 1 or 2, matching same length preferred
        # Search for closing run
        # Prefer strong if run>=2 and a closing >=2 exists, else em with 1
        candidates=[]
        k=j
        while k<end:
            if s[k]=="\\": k+=2; continue
            if s[k]=="`":
                kk=k
                while kk<end and s[kk]=="`": kk+=1
                # skip code span if matched
                f=None; q=kk
                while q<end:
                    if s[q]=="`":
                        qq=q
                        while qq<end and s[qq]=="`": qq+=1
                        if qq-q==kk-k: f=qq; break
                        q=qq
                    else: q+=1
                if f: k=f; continue
                k=kk; continue
            if s[k]==ch:
                kk=k
                while kk<end and s[kk]==ch: kk+=1
                _,can_close=self._flanking(k,kk,ch)
                if can_close and kk>k and s[j:k].strip()!="":
                    candidates.append((k,kk,kk-k))
                    # for most, nearest candidate is right; but strong nesting might need later.
                    break
                k=kk; continue
            k+=1
        if not candidates: return None,i
        k,kk,crun=candidates[0]
        if ch=="~":
            # strikethrough only if opening run is 1 or 2 (pulldown allows any? use 1/2)
            if run>2 or crun<1: return None,i
            use=run if run<=crun else crun
            inner_start=i+use; inner_end=kk-use
            # if closing side has extra tildes, they'd be left: our nxt goes past whole run? handle by leaving extras as text in outer parse
            # Simpler consume use from both; return nxt pointing to leftover closing run chars
            children=InlineParser(s[inner_start:inner_end],self.refs,self.footnotes,self.smart)._parse_range(0,inner_end-inner_start,allow_links,False)
            return Node("del",children=children), (kk-use+use)  # =kk, extras before inner_end already in inner if crun>use (inner_end=kk-use) good
        # * or _
        if run>=2 and crun>=2:
            use=2; kind="strong"
        else:
            use=1; kind="em"
        inner_start=i+use; inner_end=k+(crun-use) if False else (kk-use)
        # closing run: used delimiters are the last `use` of run? In CommonMark, excess closing delims remain outside.
        # inner text is up to start of closing run + (crun-use) leftover delimiters become literal after node.
        inner_text_end=k
        children=InlineParser(s[inner_start:inner_text_end],self.refs,self.footnotes,self.smart)._parse_range(0,inner_text_end-inner_start,allow_links,False)
        # If opening run had more than use, those extra delimiters belong inside (at beginning) in CM algorithm.
        # Our inner_start=i+use leaves extras between i+use and j as part of inner if run>use? No: inner_start is i+use < j, includes extra delims. Good.
        # Next index: skip only use closing delims from the END? Delimiter stack uses nearest etc.
        # Position after consuming use closing tokens: if crun>use, leftover should be parsed next; they are at start of closing run.
        nxt = k + use
        # But if we consumed from start, leftover delim chars are between nxt and kk and will be seen next loop? Our caller sets i=nxt, which points inside run, remaining run length crun-use. good.
        # However for strong nested like **a**, nxt=kk.
        return Node(kind,children=children), nxt

def plain_text(nodes):
    out=[]
    for nd in nodes:
        if nd.kind=="text": out.append(nd.text)
        elif nd.kind=="code": out.append(nd.text)
        elif nd.kind in ("softbreak","hardbreak"): out.append(" ")
        elif nd.kind=="html": continue
        elif nd.kind=="footnote_ref": continue
        else: out.append(plain_text(nd.children))
    return "".join(out)

def apply_smart_punctuation(text,prev_char="",next_char=""):
    # Dashes / ellipsis first (across the whole text node)
    text=text.replace("---","\u2014").replace("--","\u2013").replace("...","\u2026")
    out=[]
    n=len(text)
    for idx,ch in enumerate(text):
        if ch=='"':
            prev=out[-1] if out else prev_char
            nxt=text[idx+1] if idx+1<n else next_char
            if (not prev or prev.isspace() or prev in "([{<\u2018\u201c-") and nxt and not nxt.isspace():
                out.append("\u201c")
            else:
                out.append("\u201d")
        elif ch=="'":
            prev=out[-1] if out else prev_char
            nxt=text[idx+1] if idx+1<n else next_char
            if prev.isalnum() and nxt.isalnum():
                out.append("\u2019")
            elif (not prev or prev.isspace() or prev in "([{<\u201c\"") and nxt and nxt.isalnum():
                out.append("\u2018")
            else:
                out.append("\u2019")
        else:
            out.append(ch)
    return "".join(out)

# ---------------- block AST ----------------
class Block:
    __slots__=("kind","text","children","level","info","items","aligns","header","rows","tight","start_num","task","offset","marker_offset","custom_id","classes","attrs","label")
    def __init__(self,kind,text="",children=None,level=0,info=None,items=None,aligns=None,header=None,rows=None,tight=True,start_num=None,offset=0):
        self.kind=kind; self.text=text; self.children=children or []; self.level=level; self.info=info
        self.items=items or []; self.aligns=aligns or []; self.header=header or []; self.rows=rows or []
        self.tight=tight; self.start_num=start_num; self.task=None; self.offset=offset; self.marker_offset=offset
        self.custom_id=None; self.classes=[]; self.attrs=[]; self.label=None

class DocState:
    def __init__(self):
        self.refs={}
        self.footnotes={}  # normalized label -> Block footnote_def with children, original label in .label
        self.footnote_order=[]

def line_offset_list(text):
    lines=text.split("\n")
    offsets=[]; pos=0
    for ln in lines:
        offsets.append(pos); pos+=len(ln)+1
    return lines,offsets

class Line:
    __slots__=("text","offset")
    def __init__(self,text,offset): self.text=text; self.offset=offset

def indent_of(text):
    i=0
    while i<len(text) and text[i]==" ": i+=1
    return i

def strip_upto(text,n):
    i=0
    while i<len(text) and i<n and text[i]==" ": i+=1
    return text[i:]

class BlockParser:
    def __init__(self,state=None):
        self.state=state or DocState()
    def parse_document(self,text):
        text=text.replace("\r\n","\n").replace("\r","\n")
        raw_lines,offsets=line_offset_list(text)
        # if text ends without newline, split gives last line. If ends with newline, final '' is an extra blank line; keep (parser ignores blanks)
        lines=[Line(expand_tabs(ln),off) for ln,off in zip(raw_lines,offsets)]
        blocks=self.parse_blocks(lines)
        return blocks
    def parse_blocks(self,lines):
        blocks=[]; i=0; n=len(lines)
        while i<n:
            # skip blank
            while i<n and lines[i].text.strip()=="": i+=1
            if i>=n: break
            line=lines[i]; t=line.text; ind=indent_of(t)
            stripped=t.strip()
            # link reference defs handled in paragraph gathering, but a lone def block:
            # try footnote definition
            fn=self._try_footnote_def(lines,i)
            if fn:
                blk,consumed=fn
                self.state.footnotes[normalize_label(blk.label)]=blk
                i+=consumed; continue
            # ATX heading
            m=re.match(r'^ {0,3}(#{1,6})(?:[ \t]+(.*?)|[ \t]*)$',t)
            if m:
                content=(m.group(2) or "").rstrip()
                # closing sequence
                content=re.sub(r'[ \t]+#+[ \t]*$','',content)
                if re.fullmatch(r'#+',content): content=""
                blk=Block("heading",text=content.strip(),level=len(m.group(1)),offset=line.offset)
                self._heading_attrs(blk)
                blocks.append(blk); i+=1; continue
            # fenced code
            m=re.match(r'^ {0,3}(`{3,}|~{3,})(.*)$',t)
            if m and not (m.group(1)[0]=="`" and "`" in m.group(2)):
                blk,consumed=self._parse_fence(lines,i,m)
                blocks.append(blk); i+=consumed; continue
            # thematic break
            if is_thematic(t):
                blocks.append(Block("hr",offset=line.offset)); i+=1; continue
            # html block
            htmlb=self._try_html_block(lines,i)
            if htmlb:
                blk,consumed=htmlb; blocks.append(blk); i+=consumed; continue
            # blockquote
            if re.match(r'^ {0,3}>',t):
                blk,consumed=self._parse_blockquote(lines,i)
                blocks.append(blk); i+=consumed; continue
            # table
            tbl=self._try_table(lines,i)
            if tbl:
                blk,consumed=tbl; blocks.append(blk); i+=consumed; continue
            # list
            if self._list_marker(t) is not None:
                blk,consumed=self._parse_list(lines,i)
                blocks.append(blk); i+=consumed; continue
            # indented code
            if ind>=4:
                blk,consumed=self._parse_indented(lines,i)
                blocks.append(blk); i+=consumed; continue
            # paragraph / setext / refdefs
            blk,consumed=self._parse_paragraph(lines,i)
            if blk is not None: blocks.append(blk)
            i+=consumed
        return blocks
    def _heading_attrs(self,blk):
        text=blk.text
        m=re.search(r'[ \t]+\{\s*([^{}]*)\}\s*$',text)
        if not m: return
        content=m.group(1).strip()
        if not content: return
        # tokenize respecting quoted strings
        tokens=[]; cur=""; quote=None
        for ch in content:
            if quote:
                cur+=ch
                if ch==quote: quote=None
            elif ch in "\"'":
                quote=ch; cur+=ch
            elif ch.isspace():
                if cur: tokens.append(cur); cur=""
            else: cur+=ch
        if cur: tokens.append(cur)
        custom=None; classes=[]; attrs=[]
        for tok in tokens:
            if tok.startswith("#") and len(tok)>1: custom=tok[1:]
            elif tok.startswith(".") and len(tok)>1: classes.append(tok[1:])
            elif "=" in tok:
                k,v=tok.split("=",1)
                if len(v)>=2 and v[0]==v[-1] and v[0] in "\"'": v=v[1:-1]
                attrs.append((k,v))
            elif re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]*',tok): attrs.append((tok,None))
            else: return
        blk.custom_id=custom; blk.classes=classes; blk.attrs=attrs
        blk.text=text[:m.start()].rstrip()
    def _parse_fence(self,lines,i,m):
        fence=m.group(1); fchar=fence[0]; flen=len(fence); info=m.group(2).strip()
        ind=len(lines[i].text)-len(lines[i].text.lstrip(" "))
        content=[]; j=i+1
        while j<len(lines):
            mm=re.match(r'^ {0,3}(`{3,}|~{3,})[ \t]*$',lines[j].text)
            if mm and mm.group(1)[0]==fchar and len(mm.group(1))>=flen:
                j+=1; break
            content.append(strip_upto(lines[j].text,ind)); j+=1
        literal="\n".join(content)
        if content: literal+="\n"
        return Block("code",text=literal,info=info,offset=lines[i].offset), j-i
    def _parse_indented(self,lines,i):
        content=[]; j=i
        while j<len(lines):
            t=lines[j].text
            if t.strip()=="":
                content.append(""); j+=1; continue
            if indent_of(t)>=4:
                content.append(t[4:]); j+=1; continue
            break
        while content and content[-1]=="": content.pop()
        literal="\n".join(content)
        if content: literal+="\n"
        return Block("code",text=literal,info=None,offset=lines[i].offset), j-i
    def _try_html_block(self,lines,i):
        t=lines[i].text
        s=t.lstrip(" ")
        if len(t)-len(s)>3: return None
        typ=html_block_type(s)
        if typ is None: return None
        # type 7 cannot interrupt paragraph, but at block start ok
        content=[t]; j=i+1
        if typ in (1,2,3,4,5):
            endconds={1:re.compile(r'</(?:script|pre|style|textarea)>',re.I),2:re.compile(r'-->'),3:re.compile(r'\?>'),4:re.compile(r'>'),5:re.compile(r'\]\]>')}
            if endconds[typ].search(t):
                return Block("html",text="\n".join(content)+"\n",offset=lines[i].offset),1
            while j<len(lines):
                content.append(lines[j].text)
                if endconds[typ].search(lines[j].text): j+=1; break
                j+=1
        else:
            while j<len(lines) and lines[j].text.strip()!="":
                content.append(lines[j].text); j+=1
        return Block("html",text="\n".join(content)+"\n",offset=lines[i].offset), j-i
    def _parse_blockquote(self,lines,i):
        inner=[]; j=i
        while j<len(lines):
            t=lines[j].text
            m=re.match(r'^ {0,3}>[ \t]?',t)
            if m:
                inner.append(Line(t[m.end():], lines[j].offset+m.end())); j+=1; continue
            if t.strip()=="":
                break
            # lazy continuation: include if previous inner isn't blank and line looks like paragraph text
            if inner and inner[-1].text.strip()!="" and not self._starts_block(t):
                inner.append(Line(t,lines[j].offset)); j+=1; continue
            break
        children=self.parse_blocks(inner)
        return Block("blockquote",children=children,offset=lines[i].offset), j-i
    def _starts_block(self,t):
        if re.match(r'^ {0,3}(#{1,6})(?:[ \t]+|[ \t]*$)',t): return True
        if re.match(r'^ {0,3}(`{3,}|~{3,})',t): return True
        if is_thematic(t): return True
        if re.match(r'^ {0,3}>',t): return True
        if self._list_marker(t) is not None: return True
        if html_block_type(t.lstrip(" ")) in (1,2,3,4,5,6): return True
        return False
    def _try_table(self,lines,i):
        if i+1>=len(lines): return None
        header_line=lines[i].text
        if "|" not in header_line: return None
        aligns=parse_delimiter_row(lines[i+1].text)
        if aligns is None: return None
        header=split_table_row(header_line)
        if header is None or len(header)!=len(aligns): return None
        rows=[]; j=i+2
        while j<len(lines) and lines[j].text.strip()!="":
            if self._starts_block(lines[j].text) and "|" not in lines[j].text:
                break
            row=split_table_row(lines[j].text)
            if row is None: break
            row=(row+[""]*len(header))[:len(header)]
            rows.append(row); j+=1
        return Block("table",header=header,rows=rows,aligns=aligns,offset=lines[i].offset), j-i
    def _list_marker(self,t):
        m=re.match(r'^( {0,3})([-+*]|\d{1,9}[.)])([ \t]+|[ \t]*$)',t)
        if not m: return None
        indent=len(m.group(1)); marker=m.group(2); after=m.group(3)
        marker_end=indent+len(marker)
        rest=t[marker_end:]
        # spaces after
        spaces=len(rest)-len(rest.lstrip(" \t"))
        # An empty list item cannot interrupt paragraph etc handled by caller context; at block start fine.
        if rest.strip()=="" :
            content_col=marker_end+1
        elif spaces>=5:
            content_col=marker_end+1
        else:
            content_col=marker_end+spaces
        is_ordered=marker[0].isdigit()
        start_num=int(re.match(r'\d+',marker).group(0)) if is_ordered else None
        delim=marker[-1] if is_ordered else marker
        return {"indent":indent,"marker":marker,"content_col":content_col,"ordered":is_ordered,"start":start_num,"delim":delim,"marker_end":marker_end}
    def _parse_list(self,lines,i):
        first=self._list_marker(lines[i].text)
        list_indent=first["indent"]; ordered=first["ordered"]; delim=first["delim"]; start_num=first["start"]
        items=[]; j=i; loose=False
        while j<len(lines):
            mk=self._list_marker(lines[j].text)
            if mk is None: break
            if mk["indent"]>list_indent+3: break
            if mk["ordered"]!=ordered or mk["delim"]!=delim:
                break
            # collect item lines
            content_col=mk["content_col"]
            first_line=lines[j].text[content_col:] if len(lines[j].text)>=content_col else ""
            item_lines=[Line(first_line, lines[j].offset+content_col)]
            marker_off=lines[j].offset  # offset of line start in original (approximate for summary)
            item_offset=lines[j].offset
            content_offset=lines[j].offset+content_col
            k=j+1; blanks=0; saw_blank=False; blank_then_content=False
            ended=False
            while k<len(lines):
                t=lines[k].text
                if t.strip()=="":
                    # lookahead: is next nonblank part of this item / next item?
                    nxt=k+1
                    while nxt<len(lines) and lines[nxt].text.strip()=="": nxt+=1
                    if nxt>=len(lines):
                        k=nxt; ended=True; break
                    nmk=self._list_marker(lines[nxt].text)
                    if nmk is not None and nmk["ordered"]==ordered and nmk["delim"]==delim and nmk["indent"]<=list_indent+3:
                        loose=True; k=nxt; ended=True; break
                    if indent_of(lines[nxt].text)>=content_col:
                        saw_blank=True; item_lines.append(Line("",lines[k].offset)); k+=1; continue
                    else:
                        k=nxt if False else k  # end list after blanks
                        ended=True; break
                mk2=self._list_marker(t)
                if mk2 is not None and mk2["indent"]<content_col and mk2["ordered"]==ordered and mk2["delim"]==delim and mk2["indent"]<=list_indent+3:
                    ended=True; break
                if indent_of(t)>=content_col:
                    if saw_blank: blank_then_content=True
                    item_lines.append(Line(strip_upto(t,content_col), lines[k].offset+content_col)); k+=1; continue
                # lazy continuation line
                if item_lines and item_lines[-1].text.strip()!="" and not self._starts_block(t):
                    item_lines.append(Line(t,lines[k].offset)); k+=1; continue
                ended=True; break
            if blank_then_content: loose=True
            # remove trailing blank lines in item (don't set loose just for them)
            while item_lines and item_lines[-1].text.strip()=="": item_lines.pop()
            children=self.parse_blocks(item_lines)
            item=Block("item",children=children,offset=item_offset)
            item.marker_offset=lines[j].offset
            # store content start for summary errors in level attr? use attrs
            item.attrs=[("__content_offset",content_offset)]
            # task list detection on first child paragraph
            if children and children[0].kind=="paragraph":
                mtask=re.match(r'^\[( |x|X)\](?:[ \t]+|$)',children[0].text)
                if mtask:
                    item.task=(mtask.group(1).lower()=="x")
                    children[0].text=children[0].text[mtask.end():] if False else children[0].text
                    # mark paragraph with task prefix length for inline render skip
                    children[0].attrs=[("__task_len",mtask.end())]
            items.append(item)
            if k==j: k=j+1
            j=k
            # skip blank separation handled above; if next isn't sibling item break
        blk=Block("list",items=items,tight=not loose,start_num=start_num if ordered else None,offset=lines[i].offset)
        # store ordered flag in info
