            attrs=f' id="{escape_html_attr(hid)}"'
            if b.classes: attrs+=f' class="{escape_html_attr(" ".join(b.classes))}"'
            for ak,av in getattr(b,"attrs",[]):
                if av is None: attrs+=f' {ak}'
                else: attrs+=f' {ak}="{escape_html_attr(av)}"'
