    if text=="": return []
    parts=text.split("\n")
    if text.endswith("\n"): parts.pop()
    return [p[:-1] if p.endswith("\r") else p for p in parts]

def rust_line_classify(line):
    stripped=line.lstrip(" \t")
    lead=line[:len(line)-len(stripped)]
    if stripped.startswith("##"):
        return False, lead+stripped[1:]
    if stripped=="#":
        return True, lead
    if stripped.startswith("# "):
        return True, lead+stripped[2:]
    return False, line

def render_code_block(info,literal,cfg):
    classes=split_info(info) if info is not None else []
    if info is None:
        return f"<pre><code>{escape_html_text(literal)}</code></pre>\n"
    if not classes:
        return f"<pre><code>{escape_html_text(literal)}</code></pre>\n"
    lang=classes[0]
    class_attr="language-"+lang
    if len(classes)>1: class_attr+=" "+" ".join(classes[1:])
    class_attr_esc=escape_html_attr(class_attr)
    if lang=="rust":
        # runnable determination
        cls=set(classes)
        is_runnable=False
        if "noplayground" not in cls:
            if cfg.playground_runnable or "mdbook-runnable" in cls:
                if not ("ignore" in cls and "mdbook-runnable" not in cls):
                    is_runnable=True
        editable_mode = cfg.playground_editable and ("editable" in cls)
        segments=[]  # (hidden,text)
        use_wrapper=is_runnable and not editable_mode and ("fn main" not in literal)
        if use_wrapper:
            segments.append((True,"#![allow(unused)]"))
            segments.append((True,"fn main() {"))
        for ln in lines_of(literal):
            hidden,content=rust_line_classify(ln)
            segments.append((hidden,content))
        if use_wrapper:
            segments.append((True,"}"))
        out=[]
        for idx,(hidden,content) in enumerate(segments):
            last=idx==len(segments)-1
            esc=escape_html_text(content)
            if hidden:
                out.append(f'<span class="boring">{esc}</span>' if last else f'<span class="boring">{esc}\n</span>')
            else:
                out.append(esc if last else esc+"\n")
        code="".join(out)
        if is_runnable:
            return f'<pre><pre class="playground"><code class="{class_attr_esc}">{code}</code></pre></pre>\n'
        return f'<pre><code class="{class_attr_esc}">{code}</code></pre>\n'
    # generic hidelines
    prefix=None
    for tok in classes[1:]:
        if tok.startswith("hidelines="):
            prefix=tok[len("hidelines="):]; break
    if prefix is None:
        prefix=cfg.code_hidelines.get(lang)
    if prefix:
        out=[]
        raw_lines=literal.split("\n")
        # reconstruct with endings
        for idx,raw in enumerate(raw_lines):
            is_last_piece=idx==len(raw_lines)-1
            if is_last_piece and raw=="":
                continue
            ending="" if is_last_piece else "\n"
            line_text=raw[:-1] if raw.endswith("\r") else raw
            stripped=line_text.lstrip(" \t")
            lead_len=len(line_text)-len(stripped)
            if stripped.startswith(prefix):
                content=line_text[:lead_len]+stripped[len(prefix):]
                out.append(f'<span class="boring">{escape_html_text(content)}{ending}</span>')
            else:
                out.append(escape_html_text(line_text)+ending)
        code="".join(out)
        return f'<pre><code class="{class_attr_esc}">{code}</code></pre>\n'
    return f'<pre><code class="{class_attr_esc}">{escape_html_text(literal)}</code></pre>\n'

# Plain text extraction for search/headings
def blocks_plain_text(blocks,parser_state=None):
    parts=[]
    def add_block(b):
        if b.kind in ("paragraph","heading"):
            txt=inline_plain(b.text,parser_state)
            if txt: parts.append(txt)
        elif b.kind=="code":
            t=b.text.strip("\n")
            if t: parts.append(t)
        elif b.kind=="table":
            cells=[]
            for c in b.header: cells.append(inline_plain(c,parser_state))
            for row in b.rows:
                for c in row: cells.append(inline_plain(c,parser_state))
            parts.extend([c for c in cells if c])
        elif b.kind=="list":
            for item in b.items:
                for c in item.children: add_block(c)
        elif b.kind in ("blockquote",):
            for c in b.children: add_block(c)
        elif b.kind=="item":
            for c in b.children: add_block(c)
    for b in blocks: add_block(b)
    # Join with spaces but preserve code block internal newlines: caller handles if needed
    return parts

def inline_plain(text,state):
    refs=state.refs if state else {}
    fns=state.footnotes if state else {}
    nodes=InlineParser(text,refs,fns).parse()
    txt=plain_text(nodes)
    return " ".join(txt.split())
