class TemplateError(Exception):
    def __init__(self,msg,line=1,col=1,template_name="index"):
        self.msg=msg; self.line=line; self.col=col; self.template_name=template_name
    def to_md_error(self):
        # Chain matching handlebars crate-ish render errors
        if self.msg.startswith("Template error:"):
            return MdError("Rendering failed",[self.msg])
        return MdError("Rendering failed",[f'Error rendering "{self.template_name}" line {self.line}, col {self.col}: {self.msg}', self.msg])

class SafeString(str): pass

MISSING=object()

def is_truthy(v,include_zero=False):
    if v is MISSING or v is None: return False
    if v is False: return False
    if isinstance(v,(list,dict,str)) and len(v)==0: return False
    if isinstance(v,(int,float)) and not isinstance(v,bool) and v==0: return include_zero
    return True

def to_display(v):
    if v is MISSING or v is None: return ""
    if v is True: return "true"
    if v is False: return "false"
    if isinstance(v,(dict,list)): return "[object]"
    if isinstance(v,float): return ('%g'%v)
    return str(v)

