        if name=="raw":
            return ""
        # custom block helpers
        if name in self.helpers:
            vals=[self.eval_atom(p,ctx,state) for p in params]
            hvals={k:self.eval_atom(v,ctx,state) for k,v in hashkw.items()}
            engine=self
            def fn(context_value=MISSING,locals_=None):
