class SummaryError(MdError): pass

def line_col_of(text,byte_offset_chars):
    # byte_offset_chars is a Python char offset; convert to byte offset like Rust ranges
    prefix=text[:byte_offset_chars]
    line=prefix.count("\n")+1
    last=prefix.rfind("\n")
    if last>=0:
        col=len(prefix[last:].encode('utf-8'))  # prefix[last:] includes newline char as 1 byte, so first char on line => col1
        # compute bytes since newline (excluding?) Rust get_line_column: col = byte_offset - last_newline_byte_index
        col=len(prefix.encode('utf-8'))-len(text[:last].encode('utf-8')) if False else len(text[:byte_offset_chars].encode('utf-8'))-len(text[:last].encode('utf-8'))
    else:
        col=len(prefix.encode('utf-8'))
    return line,col

class SummaryParser:
    def __init__(self,text,filename):
        self.text=text; self.filename=filename
        self.items=[]
        self.root_counter=0
    def err(self,cause,offset,inner_chain):
        line,col=line_col_of(self.text,offset)
        chain=[f'Summary parsing failed for file="{self.filename}"']
        chain.extend(inner_chain)
        chain.append(f"failed to parse SUMMARY.md line {line}, column {col}: {cause}")
        raise MdError(chain[0],chain[1:])
    def parse(self):
        parser=BlockParser(); blocks=parser.parse_document(self.text); self.parser_state=parser.state
        i=0; mode="prefix"; after_part=False
        if blocks and blocks[0].kind=="heading" and blocks[0].level==1:
            log.debug("mdbook_summary","Found a h1 in the SUMMARY"); i=1
        log.debug("mdbook_summary","Parsing prefix items")
        while i<len(blocks):
