                    self.items.append({"PartTitle":self._inline_text(b.text)}); mode="numbered"; log.debug("mdbook_summary","Parsing numbered chapters at level 0"); after_part=True; i+=1; continue
                if b.kind=="hr": self.items.append("Separator"); i+=1; continue
                if b.kind=="list":
