                    i+=1; continue
                i+=1; continue
            if mode=="numbered":
                if b.kind=="list":
                    after_part=False
                    self._process_list(b,parent_names=[],parent_number=[])
                    i+=1; continue
                if b.kind=="heading" and b.level==1:
                    self.items.append({"PartTitle":self._inline_text(b.text)}); after_part=True; i+=1; continue
                if b.kind=="hr": self.items.append("Separator"); after_part=False; i+=1; continue
                if b.kind=="paragraph":
