    def _inline_text(self,text):
        nodes=InlineParser(text,self.parser_state.refs,self.parser_state.footnotes).parse()
        return plain_text(nodes)
    def _links_in(self,text):
        nodes=InlineParser(text,self.parser_state.refs,self.parser_state.footnotes).parse()
        out=[]
        def walk(ns):
            for nd in ns:
                if nd.kind=="link": out.append((plain_text(nd.children),nd.dest))
                if nd.children: walk(nd.children)
        walk(nodes); return out
    def _process_list(self,blk,parent_names,parent_number):
        # For root, counters continue via self.root_counter; for nested use local counter in caller wrapper
        # This function is only called for root; nested handled recursively in _process_items
        self._process_items(blk.items,parent_names,parent_number,container=self.items,is_root=True)
    def _process_items(self,items,parent_names,parent_number,container,is_root=False):
        counter=0
        for item in items:
            # find first paragraph (link container)
            first=None
            for child in item.children:
                if child.kind in ("paragraph","heading","code","html"):
                    first=child; break
                # list as first block -> no link
                if child.kind=="list": break
            # determine first inline token
            name=None; dest=None; err_off=item.offset; err_event='End(Item)'
            if first is not None and first.kind=="paragraph":
                nodes=InlineParser(first.text,self.parser_state.refs,self.parser_state.footnotes).parse()
                # first non-softbreak
                first_node=None
                for nd in nodes:
                    if nd.kind not in ("softbreak",): first_node=nd; break
                content_off=item.offset
                for ak,av in getattr(item,"attrs",[]):
                    if ak=="__content_offset": content_off=av
                err_off=content_off
