    # validate roughly like serde
    if not isinstance(data,dict):
        raise MdError(f'Unable to parse the preprocessed book from "{pre_name}" processor',[f"invalid type: {type(data).__name__}, expected struct Book at line 1 column 1"])
    if "sections" not in data:
        # serde_json missing field col is end-ish; approximate using compact length
        s=json.dumps(data,separators=(",",":"))
        raise MdError(f'Unable to parse the preprocessed book from "{pre_name}" processor',[f"missing field `sections` at line 1 column {len(s)}"])
    secs=data["sections"]
    if not isinstance(secs,list):
        raise MdError(f'Unable to parse the preprocessed book from "{pre_name}" processor',["invalid type: sequence, expected a sequence at line 1 column 1"])
    def conv(items):
        out=[]
        for it in items:
            if it=="Separator": out.append("Separator"); continue
            if isinstance(it,dict) and "PartTitle" in it:
                out.append({"PartTitle":str(it["PartTitle"])}); continue
            if isinstance(it,dict) and "Chapter" in it:
                c=it["Chapter"]
                for field in ["name","content","number","sub_items","path","source_path","parent_names"]:
                    if not isinstance(c,dict) or field not in c:
                        s=json.dumps(it,separators=(",",":"))
                        raise MdError(f'Unable to parse the preprocessed book from "{pre_name}" processor',[f"missing field `{field}` at line 1 column {len(s)}"])
                out.append(chapter(str(c["name"]),str(c["content"]),
                    c["number"] if (c["number"] is None or isinstance(c["number"],list)) else c["number"],
                    conv(c["sub_items"]) if isinstance(c["sub_items"],list) else [],
                    c["path"] if (c["path"] is None or isinstance(c["path"],str)) else str(c["path"]),
                    c["source_path"] if (c["source_path"] is None or isinstance(c["source_path"],str)) else str(c["source_path"]),
                    list(c["parent_names"]) if isinstance(c["parent_names"],list) else []))
                continue
            raise MdError(f'Unable to parse the preprocessed book from "{pre_name}" processor',["unknown variant at line 1 column 1"])
        return out
    return {"sections":conv(secs)}

def iter_items(book):
    stack=list(book.get("sections",[]))
    # depth-first generation
    res=[]
    def walk(items):
        for it in items:
            res.append(it)
            if isinstance(it,dict) and "sub_items" in it:
                walk(it["sub_items"])
    walk(book.get("sections",[])); return res
def iter_chapters(book):
    return [it for it in iter_items(book) if isinstance(it,dict) and "name" in it]

class SummaryError(MdError): pass

def line_col_of(text,byte_offset_chars):
    # byte_offset_chars is a Python char offset; convert to byte offset like Rust ranges
    prefix=text[:byte_offset_chars]
    line=prefix.count("\n")+1
    last=prefix.rfind("\n")
    if last>=0:
        col=len(prefix[last:].encode('utf-8'))  # prefix[last:] includes newline char as 1 byte, so first char on line => col1
        # compute bytes since newline (excluding?) Rust get_line_column: col = byte_offset - last_newline_byte_index
        col=len(prefix.encode('utf-8'))-len(text[:last].encode('utf-8')) if False else len(text[:byte_offset_chars].encode('utf-8'))-len(text[:last].encode('utf-8'))
    else:
        col=len(prefix.encode('utf-8'))
    return line,col

class SummaryParser:
    def __init__(self,text,filename):
        self.text=text; self.filename=filename
        self.items=[]
        self.root_counter=0
    def err(self,cause,offset,inner_chain):
        line,col=line_col_of(self.text,offset)
        chain=[f'Summary parsing failed for file="{self.filename}"']
        chain.extend(inner_chain)
        chain.append(f"failed to parse SUMMARY.md line {line}, column {col}: {cause}")
        raise MdError(chain[0],chain[1:])
    def parse(self):
        parser=BlockParser(); blocks=parser.parse_document(self.text); self.parser_state=parser.state
        i=0; mode="prefix"; after_part=False
        if blocks and blocks[0].kind=="heading" and blocks[0].level==1:
            log.debug("mdbook_summary","Found a h1 in the SUMMARY"); i=1
        log.debug("mdbook_summary","Parsing prefix items")
        while i<len(blocks):
            b=blocks[i]
            if mode=="prefix":
                if b.kind=="heading" and b.level==1:
                    self.items.append({"PartTitle":self._inline_text(b.text)}); mode="numbered"; log.debug("mdbook_summary","Parsing numbered chapters at level 0"); after_part=True; i+=1; continue
                if b.kind=="hr": self.items.append("Separator"); i+=1; continue
                if b.kind=="list":
                    mode="numbered"; log.debug("mdbook_summary","Parsing numbered chapters at level 0")
                    continue  # reprocess as numbered
                if b.kind=="paragraph":
                    for name,dest in self._links_in(b.text):
                        self.items.append(chapter(name,path=dest if dest!="" else None,source_path=dest if dest!="" else None))
                    i+=1; continue
                i+=1; continue
            if mode=="numbered":
                if b.kind=="list":
                    after_part=False
                    self._process_list(b,parent_names=[],parent_number=[])
                    i+=1; continue
                if b.kind=="heading" and b.level==1:
                    self.items.append({"PartTitle":self._inline_text(b.text)}); after_part=True; i+=1; continue
                if b.kind=="hr": self.items.append("Separator"); after_part=False; i+=1; continue
                if b.kind=="paragraph":
                    if after_part:
                        after_part=False; i+=1; continue
                    mode="suffix"; log.debug("mdbook_summary","Parsing suffix items")
                    continue
                if b.kind=="table":
                    after_part=False; mode="suffix"; i+=1; continue
                # other blocks ignored
                after_part=False; i+=1; continue
            if mode=="suffix":
                if b.kind=="list" or (b.kind=="heading" and b.level==1):
                    self.err("Suffix chapters cannot be followed by a list",b.offset,["There was an error parsing the suffix chapters"])
                if b.kind=="hr": self.items.append("Separator"); i+=1; continue
                if b.kind=="paragraph":
                    for name,dest in self._links_in(b.text):
                        self.items.append(chapter(name,path=dest if dest!="" else None,source_path=dest if dest!="" else None))
                    i+=1; continue
                i+=1; continue
        if mode=="prefix":
            log.debug("mdbook_summary","Parsing numbered chapters at level 0")
            log.debug("mdbook_summary","Parsing suffix items")
        return {"sections":self.items}
    def _inline_text(self,text):
        nodes=InlineParser(text,self.parser_state.refs,self.parser_state.footnotes).parse()
        return plain_text(nodes)
    def _links_in(self,text):
        nodes=InlineParser(text,self.parser_state.refs,self.parser_state.footnotes).parse()
        out=[]
        def walk(ns):
            for nd in ns:
                if nd.kind=="link": out.append((plain_text(nd.children),nd.dest))
                if nd.children: walk(nd.children)
        walk(nodes); return out
    def _process_list(self,blk,parent_names,parent_number):
        # For root, counters continue via self.root_counter; for nested use local counter in caller wrapper
        # This function is only called for root; nested handled recursively in _process_items
        self._process_items(blk.items,parent_names,parent_number,container=self.items,is_root=True)
    def _process_items(self,items,parent_names,parent_number,container,is_root=False):
        counter=0
        for item in items:
            # find first paragraph (link container)
            first=None
            for child in item.children:
                if child.kind in ("paragraph","heading","code","html"):
                    first=child; break
                # list as first block -> no link
                if child.kind=="list": break
            # determine first inline token
            name=None; dest=None; err_off=item.offset; err_event='End(Item)'
            if first is not None and first.kind=="paragraph":
                nodes=InlineParser(first.text,self.parser_state.refs,self.parser_state.footnotes).parse()
                # first non-softbreak
                first_node=None
                for nd in nodes:
                    if nd.kind not in ("softbreak",): first_node=nd; break
                content_off=item.offset
                for ak,av in getattr(item,"attrs",[]):
                    if ak=="__content_offset": content_off=av
                err_off=content_off
                if first_node is None:
                    err_event='End(Item)'; err_off=item.offset
                elif first_node.kind=="link":
                    name=plain_text(first_node.children); dest=first_node.dest
                else:
                    err_event=event_debug(first_node)
                    # offset: content start (approx char offset of paragraph content in original summary)
                    # first_node offset within line: item content offset + leading spaces in first.text?
                    # first.text for list item paragraph preserves? parse_blocks paragraph text is stripped per line,
                    # so content_off points to first visible char. Good enough.
                    log.warn("mdbook_summary",f"Expected a start of a link, actually got Some({err_event})")
                    self.err("The link items for nested chapters must only contain a hyperlink",err_off,
                              ["There was an error parsing the numbered chapters","There was an error parsing the numbered chapters"])
            else:
                # empty or starts with non-paragraph
                if first is None:
                    err_event='End(Item)'
                    log.warn("mdbook_summary",f"Expected a start of a link, actually got Some({err_event})")
                    self.err("The link items for nested chapters must only contain a hyperlink",item.offset,
                              ["There was an error parsing the numbered chapters","There was an error parsing the numbered chapters"])
                else:
                    err_event=f"Start({first.kind})"
                    log.warn("mdbook_summary",f"Expected a start of a link, actually got Some({err_event})")
                    self.err("The link items for nested chapters must only contain a hyperlink",item.offset,
                              ["There was an error parsing the numbered chapters","There was an error parsing the numbered chapters"])
            if is_root:
                self.root_counter+=1; num=[self.root_counter]
            else:
                counter+=1; num=list(parent_number)+[counter]
            ch=chapter(name,number=num,path=dest if dest!="" else None,source_path=dest if dest!="" else None,parent_names=list(parent_names))
            container.append(ch)
            # nested lists
            for child in item.children:
                if child.kind=="list":
                    self._process_items(child.items,parent_names+[name],num,container=ch["sub_items"],is_root=False)

def event_debug(nd):
    if nd.kind=="text": return f"Text(Borrowed({rust_debug_str(nd.text)}))"
    if nd.kind=="code": return f"Code(Borrowed({rust_debug_str(nd.text)}))"
    if nd.kind=="strong": return "Start(Strong)"
    if nd.kind=="em": return "Start(Emphasis)"
    if nd.kind=="del": return "Start(Strikethrough)"
    if nd.kind=="image": return f'Start(Image {{ link_type: Inline, dest_url: Borrowed({rust_debug_str(nd.dest or "")}), title: Borrowed({rust_debug_str(nd.title or "")}), id: Borrowed("") }})'
    if nd.kind=="html": return f"InlineHtml(Borrowed({rust_debug_str(nd.text)}))"
    if nd.kind=="link": return "Start(Link)"
    return f"{nd.kind}"

def load_book(root,dest_override=None,for_clean=False):
    cfg=load_config(root)
    src_dir=cfg.source_dir()
    summary_path=path_join(src_dir,"SUMMARY.md")
    # Open like Rust: File::open errors -> context; read errors bare
    try:
        f=open(summary_path,'rb')
    except OSError as e:
        raise MdError(f'Couldn\'t open SUMMARY.md in "{src_dir}" directory',[os_error_str(e)])
    try:
        data=f.read()
    except OSError as e:
        raise MdError(os_error_str(e))
    finally:
        try:f.close()
        except Exception:pass
    try:
        summary_text=data.decode('utf-8')
    except UnicodeDecodeError:
        raise MdError("stream did not contain valid UTF-8")
    book=SummaryParser(summary_text,summary_path).parse()
    # create missing
    if cfg.build.create_missing:
        try:
            for ch in iter_chapters(book):
                sp=ch.get("source_path")
                if sp is None: continue
                full=path_join(src_dir,sp) if not os.path.isabs(sp) else sp
                if not os.path.exists(full):
                    create_missing_file(full,ch["name"])
        except MdError:
            raise
        except OSError as e:
            raise e
    # load contents
    log.debug("mdbook_driver::load","Loading the book from disk")
    for ch in iter_chapters(book):
        sp=ch.get("source_path")
        if sp is None:
            ch["content"]=""; continue
        full=path_join(src_dir,sp) if not os.path.isabs(sp) else sp
        log.debug("mdbook_driver::load",f'Loading {ch["name"]} ({sp})')
        try:
            f=open(full,'rb')
        except OSError as e:
            raise MdError(f"Chapter file not found, {sp}",[os_error_str(e)])
        try:
            data=f.read()
        except OSError as e:
            raise MdError(f'Unable to read "{ch["name"]}" ({full})',[os_error_str(e)])
        finally:
            f.close()
        try:
            ch["content"]=data.decode('utf-8')
        except UnicodeDecodeError:
            raise MdError(f'Unable to read "{ch["name"]}" ({full})',["stream did not contain valid UTF-8"])
    return cfg,book

def create_missing_file(full,name):
    try:
        parent=os.path.dirname(full)
        if parent: os.makedirs(parent,exist_ok=True)
        with open(full,'x',encoding='utf-8') as fh:
            fh.write(f"# {name}\n")
    except FileExistsError:
        return
    except OSError as e:
        raise MdError("Unable to create missing chapters",[f"Unable to create missing file: {full}",os_error_str(e)])

# ------------- builtin preprocessors -------------
ANCHOR_RE=re.compile(r'ANCHOR:\s*([\w_-]+)')
ANCHOR_END_RE=re.compile(r'ANCHOR_END:\s*([\w_-]+)')
LINK_RE=re.compile(r'(\\)?\{\{\s*#(include|rustdoc_include|playground)\s+([^\s}]+)([^\}]*?)\s*\}\}',re.S)

def rust_lines(text):
    if text=="": return []
    parts=text.split("\n")
    if text.endswith("\n"): parts.pop()
    return [p[:-1] if p.endswith("\r") else p for p in parts]

def parse_include_range(lines,spec_parts):
    # spec_parts: after file, list of strings split by ':'
    if not spec_parts: return lines,None
    second=spec_parts[0]
    def parse_usize(s):
        if re.fullmatch(r'\+?\d+',s):
            try:
                v=int(s)
                return v if v<2**64 else None
            except Exception: return None
        return None
    if len(spec_parts)==1:
        if second=="": return lines,None
        n=parse_usize(second)
        if n is not None:
            start=max(n-1,0)
            return lines[start:start+1], ("range",(start,start+1))
        return anchor_lines(lines,second),("anchor",second)
    # range or anchor form
    if second=="" or parse_usize(second) is not None:
        start_n=parse_usize(second) if second!="" else None
        end_s=spec_parts[1] if len(spec_parts)>1 else ""
        end_n=parse_usize(end_s) if end_s!="" else None
        start=max(start_n-1,0) if start_n is not None else 0
        end=end_n if end_n is not None else len(lines)
        return lines[start:end],("range",(start,end))
    return anchor_lines(lines,second),("anchor",second)

def anchor_lines(lines,name):
    out=[]; inside=False
    for ln in lines:
        m=ANCHOR_RE.search(ln); me=ANCHOR_END_RE.search(ln)
        if not inside:
            if m and m.group(1)==name: inside=True
            continue
        else:
            if me and me.group(1)==name: break
            if ANCHOR_RE.search(ln) or ANCHOR_END_RE.search(ln): continue
            out.append(ln)
    return out

def rustdoc_include_lines(lines,spec_parts):
    if not spec_parts:
        return lines
    second=spec_parts[0]
    def parse_usize(s):
        return int(s) if re.fullmatch(r'\+?\d+',s) and int(s)<2**64 else None
    out=[]
    # anchor mode
    if len(spec_parts)>=1 and second!="" and parse_usize(second) is None:
        name=second; inside=False; done=False
        for ln in lines:
            has_anchor=ANCHOR_RE.search(ln); has_end=ANCHOR_END_RE.search(ln)
            if not inside and not done:
                if has_anchor and has_anchor.group(1)==name:
                    inside=True; continue
                if has_anchor or has_end: continue
                out.append("# "+ln); continue
            if inside:
                if has_end and has_end.group(1)==name:
                    inside=False; done=True; continue
                if has_anchor or has_end: continue
                out.append(ln); continue
            # after done
            if has_anchor or has_end: continue
            out.append("# "+ln)
        return out
    # range mode
    selected,info=parse_include_range(lines,spec_parts)
    if info and info[0]=="range":
        start,end=info[1]
        for idx,ln in enumerate(lines):
            if start<=idx<end: out.append(ln)
            else: out.append("# "+ln)
        return out
    return [("# "+ln if ln not in selected else ln) for ln in lines]

def replace_links(content,base_dir,src_dir):
    return _replace_links(content,base_dir,0)
def _replace_links(content,base_dir,depth):
    if depth>20:
        return content
    result=[]; last=0
    for m in LINK_RE.finditer(content):
        result.append(content[last:m.start()])
        last=m.end()
        full=m.group(0); escaped=m.group(1)
        if escaped:
            result.append(full[1:]); continue
        typ=m.group(2); target=m.group(3); args_str=m.group(4) or ""
        args=args_str.split()
        if typ=="playground":
            file_part=target; spec=[]
        else:
            comp=target.split(":")
            file_part=comp[0]; spec=comp[1:]
        resolved=path_join(base_dir,file_part) if not os.path.isabs(file_part) else file_part
        try:
            file_text=read_text_file(resolved)
        except OSError as e:
            log.error("mdbook_driver::builtin_preprocessors::links",f'Error updating "{full}", Could not read file for link {full} ({resolved})')
            log.warn("mdbook_driver::builtin_preprocessors::links",f"Caused By: {os_error_str(e)}")
            result.append(full); continue
        lines=rust_lines(file_text)
        new_base=os.path.dirname(resolved) or base_dir
        if typ=="include":
            selected,_=parse_include_range(lines,spec)
            joined="\n".join(selected)
            result.append(_replace_links(joined,new_base,depth+1))
        elif typ=="rustdoc_include":
            selected=rustdoc_include_lines(lines,spec)
            joined="\n".join(selected)
            result.append(joined)
        elif typ=="playground":
            joined="\n".join(lines)
            attrs="".join(","+a for a in args)
            result.append(f"```rust{attrs}\n{joined}\n```\n")
    result.append(content[last:])
    return "".join(result)

def links_preprocess(book,cfg):
    src_dir=cfg.source_dir()
    b=copy.deepcopy(book)
    for ch in iter_chapters(b):
        if not ch.get("content"): continue
        sp=ch.get("source_path")
        if sp:
            base=path_join(src_dir,os.path.dirname(sp)) if os.path.dirname(sp) else src_dir
        else:
            base=src_dir
        ch["content"]=replace_links(ch["content"],base,src_dir)
    return b

def index_preprocess(book,cfg):
    b=copy.deepcopy(book)
    for ch in iter_chapters(b):
        p=ch.get("path")
        if not p: continue
        name=file_name(p); stem,ext=file_stem_ext(name)
        if stem.lower()=="readme" and name.lower().startswith("readme"):
            # Rust file_stem check: stem eq_ignore_ascii_case README
            if stem.encode().lower()==b"readme":
                parent=p[:len(p)-len(name)]
                ch["path"]=parent+"index.md"
    return b

# ------------- preprocessor ordering / external ------------
def preprocessor_order(cfg):
    pre_table=cfg.preprocessor_table()  # may raise MdError
    names=set(pre_table.keys())
    if cfg.build.use_default_preprocessors:
        names.add("index"); names.add("links")
    # edges name -> set of names that must come after it
    edges={n:set() for n in names}
    indeg={n:0 for n in names}
    def add_edge(a,b):
        if a in names and b in names and b not in edges[a]:
            edges[a].add(b)
    for name in names:
        conf=pre_table.get(name,{}) if isinstance(pre_table.get(name),dict) else {}
        before=conf.get("before") if isinstance(conf,dict) else None
        after=conf.get("after") if isinstance(conf,dict) else None
        if isinstance(before,list):
            for x in before:
                if isinstance(x,str): add_edge(name,x)
        if isinstance(after,list):
            for x in after:
                if isinstance(x,str): add_edge(x,name)
    # Kahn lexicographically smallest
    result=[]; remaining=set(names)
    # compute indegrees repeatedly
    while remaining:
        avail=[]
        for n in sorted(remaining):
            if not any((n in edges[m]) for m in remaining):
                avail.append(n)
        if not avail:
            raise MdError("Cyclic dependency detected in preprocessors")
        pick=avail[0]; result.append(pick); remaining.remove(pick)
    return result,pre_table

def shell_split(cmd):
    return shlex.split(cmd,posix=True)

def run_external_preprocessor(name,conf,book,cfg,renderer):
    renderers=conf.get("renderers") if isinstance(conf,dict) else None
    if isinstance(renderers,list) and all(isinstance(x,str) for x in renderers):
        if renderer not in renderers:
            return book,False
    cmdstr=conf.get("command") if isinstance(conf,dict) else None
    if not isinstance(cmdstr,str): cmdstr=f"mdbook-{name}"
    try:
        parts=shell_split(cmdstr)
    except Exception as e:
        log.warn("mdbook_driver::builtin_preprocessors::cmd",f'Unable to create the command for the "{name}" preprocessor, {e}')
        return book,False
    if not parts:
        log.warn("mdbook_driver::builtin_preprocessors::cmd",f'Unable to create the command for the "{name}" preprocessor, Command string was empty')
        return book,False
    prog=parts[0]
    # supports
    try:
        sup=subprocess.run(parts+["supports",renderer])
    except FileNotFoundError as e:
        log.warn("mdbook_driver::builtin_preprocessors::cmd",f'The command wasn\'t found, is the "{name}" preprocessor installed?')
        log.warn("mdbook_driver::builtin_preprocessors::cmd",f"\tCommand: {prog}")
        return book,False
    except OSError as e:
        log.warn("mdbook_driver::builtin_preprocessors::cmd",f'The command wasn\'t found, is the "{name}" preprocessor installed?')
        log.warn("mdbook_driver::builtin_preprocessors::cmd",f"\tCommand: {prog}")
        return book,False
    if sup.returncode!=0:
        return book,False
    ctx={"root":cfg.root,"config":cfg.serialize(),"renderer":renderer,"mdbook_version":__import__('app.util',fromlist=['VERSION']).VERSION}
    payload=json.dumps([ctx,book_to_json(copy.deepcopy(book))],ensure_ascii=False,separators=(",",":"))
    try:
        proc=subprocess.run(parts,input=payload.encode('utf-8'),stdout=subprocess.PIPE)
    except OSError as e:
        raise MdError(f'Unable to run the "{name}" preprocessor',[os_error_str(e)])
    if proc.returncode!=0:
        if proc.returncode>0: status=f"{proc.returncode} status"
        else: status=f"signal: {-proc.returncode} status"
        raise MdError(f'The "{name}" preprocessor exited unsuccessfully with exit status: {status}')
    try:
        data=json.loads(proc.stdout.decode('utf-8'))
    except Exception as e:
        # serde_json-ish messages
        msg=serde_json_error(proc.stdout.decode('utf-8',errors='replace'),e)
        raise MdError(f'Unable to parse the preprocessed book from "{name}" processor',[msg])
    return book_from_json(data,name),True

def serde_json_error(text,e):
    # Approximate serde_json errors for common cases
    if text.strip() and text.strip()[0] not in '{[0123456789"tfn-':
        # first ident token
        return "expected ident at line 1 column 2"
    if hasattr(e,'lineno'):
        return f"{e.msg} at line {e.lineno} column {e.colno}"
    return str(e)

def run_preprocessors(book,cfg,renderer):
    order,pre_table=preprocessor_order(cfg)
    result=copy.deepcopy(book)
    for name in order:
        if name=="index":
            if renderer=="html":
                log.debug("mdbook_driver::mdbook","Running the index preprocessor.")
                result=index_preprocess(result,cfg)
            continue
        if name=="links":
            log.debug("mdbook_driver::mdbook","Running the links preprocessor.")
            result=links_preprocess(result,cfg); continue
        conf=pre_table.get(name,{})
        result,_=run_external_preprocessor(name,conf,result,cfg,renderer)
    return result

class MDBook:
