class Theme:
    def __init__(self):
        self.index_hbs=load_text("theme/index.hbs")
        self.head_hbs=""; self.header_hbs=""; self.redirect_hbs=REDIRECT_TEMPLATE
        self.static={}       # logical -> (bytes, hashed?)
        self.order=[]        # logical paths in write order
        self.favicon_png=True; self.favicon_svg=True
        self.copy_fonts_effective=True
        for logical,asset,hashed in THEME_STATIC:
            self._set(logical,load_asset(asset),hashed)
    def _set(self,logical,data,hashed=True):
        if logical not in self.static: self.order.append(logical)
        self.static[logical]=(data,hashed)
    def _remove(self,logical):
        if logical in self.static:
            del self.static[logical]; self.order.remove(logical)

def _read_theme_text(path):
    # Rust reads bytes then String::from_utf8 for templates
    with open(path,'rb') as f: data=f.read()
    err=rust_utf8_error(data)
    if err: raise MdError(err)
    return data.decode('utf-8')

def load_theme(cfg,html_cfg):
    theme=Theme()
    if html_cfg.theme:
        tdir=html_cfg.theme if os.path.isabs(html_cfg.theme) else path_join(cfg.root,html_cfg.theme)
        if not os.path.isdir(tdir):
            raise MdError("Rendering failed",[f"theme dir {tdir} does not exist"])
    else:
        tdir=path_join(cfg.root,"theme")
        if not os.path.isdir(tdir):
            # still need fonts defaults per copy_fonts config
            theme.copy_fonts_effective=html_cfg.copy_fonts
            if html_cfg.copy_fonts:
                for p in FONT_FILES: theme._set(p,load_asset(FONT_ASSET[p]),p not in NO_HASH_FONTS)
            return theme
    # templates
    try:
        for fname,attr in [("index.hbs","index_hbs"),("head.hbs","head_hbs"),("header.hbs","header_hbs"),("redirect.hbs","redirect_hbs")]:
            p=path_join(tdir,fname)
            if os.path.exists(p):
                setattr(theme,attr,_read_theme_text(p))
        # favicon special: if either present, only those
        has_svg=os.path.exists(path_join(tdir,"favicon.svg")); has_png=os.path.exists(path_join(tdir,"favicon.png"))
        if has_svg or has_png:
            if not has_svg: theme._remove("favicon.svg"); theme.favicon_svg=False
            if not has_png: theme._remove("favicon.png"); theme.favicon_png=False
        # static overrides
        for logical in THEME_OVERRIDES:
            p=path_join(tdir,logical)
            if os.path.exists(p):
                with open(p,'rb') as f: data=f.read()
                theme._set(logical,data,theme.static.get(logical,(None,True))[1])
        # fonts
        fonts_dir=path_join(tdir,"fonts")
        custom_fonts_css=os.path.exists(path_join(fonts_dir,"fonts.css"))
        if custom_fonts_css:
            theme.copy_fonts_effective=True
            # add all files under theme/fonts recursively
            for dirpath,dirnames,filenames in os.walk(fonts_dir):
                dirnames.sort()
                for fn in sorted(filenames):
                    full=os.path.join(dirpath,fn)
                    rel=os.path.relpath(full,fonts_dir).replace(os.sep,"/")
                    logical="fonts/"+rel
                    with open(full,'rb') as f: data=f.read()
                    theme._set(logical,data,True)
        else:
            theme.copy_fonts_effective=html_cfg.copy_fonts
            if html_cfg.copy_fonts:
                for p in FONT_FILES: theme._set(p,load_asset(FONT_ASSET[p]),p not in NO_HASH_FONTS)
                if os.path.isdir(fonts_dir):
                    for dirpath,dirnames,filenames in os.walk(fonts_dir):
                        dirnames.sort()
                        for fn in sorted(filenames):
                            full=os.path.join(dirpath,fn)
                            rel=os.path.relpath(full,fonts_dir).replace(os.sep,"/")
                            logical="fonts/"+rel
                            with open(full,'rb') as f: data=f.read()
                            theme._set(logical,data,True)
    except MdError:
        raise
    except OSError as e:
        raise MdError(os_error_str(e))
    return theme
