    def process_resources(self,content,logical):
        # only for text-y content that decodes
        try: text=content.decode('utf-8')
        except Exception: return content
        if "{{" not in text: return content
        depth=logical.count("/")
        # logical may be absolute additional path; depth based on directory components in output path relative to dest if absolute outside? use output logical dir count excluding leading /
        out_logical=self.static[logical].output
        dirpart=out_logical.rsplit("/",1)[0] if "/" in out_logical else ""
        depth=len([p for p in dirpart.split("/") if p]) if dirpart else 0
        if os.path.isabs(out_logical):
            # resources in absolute additional files: path_to_root relative to dest isn't well-defined; use depth from logical? keep simple: ../ * depth of dest-relative? Use original logical depth relative components
            depth=len([p for p in logical.split("/")[:-1] if p])
        ptr="../"*depth
        def repl(m):
            target=self.resource_map.get(m.group(1),m.group(1))
            if os.path.isabs(target): return target
