            ctx["git_repository_edit_url"]=self.html.edit_url_template.replace("{path}",editpath)
        outurl=html_url_path(ch["path"]) if ch.get("path") else None
        if outurl and outurl in self.fragment_maps:
            ctx["fragment_map"]=self.fragment_maps[outurl]
