    def render_chapter(self,ch,base,flat_idx,alias_index=False):
        html=self.html
        renderer=MarkdownRenderer(html,chapter_path=None,print_mode=False)
        content_html=renderer.render(ch.get("content",""))
        if alias_index:
            path_value="index.md"; out_rel="index.html"; ptr=""
        else:
            path_value=ch["path"]; out_rel=html_url_path(ch["path"]); ptr=path_to_root_for(out_rel)
        ctx=self.chapter_context(base,ch,content_html,path_value,ptr,alias_index)
        try:
