    def render_404(self,base):
        html=self.html
        if html.input_404=="":
            return
        configured=html.input_404 is not None
        input_name=html.input_404 if configured else "404.md"
        output_name=input_name.replace(".md",".html") if configured else "404.html"
        src_dir=self.cfg.source_dir()
        in_path=path_join(src_dir,input_name) if not os.path.isabs(input_name) else input_name
        if os.path.exists(in_path) or configured:
            try: content=read_text_file(in_path)
            except OSError as e:
                raise MdError("Rendering failed",[f'unable to open 404 input file "{in_path}"',os_error_str(e)])
        else:
            content="# Document not found (404)\n\nThis URL is invalid, sorry. Please use the navigation bar or search to continue.\n"
        renderer=MarkdownRenderer(html)
        content_html=renderer.render(content)
        ctx=dict(base)
        book_title=self.cfg.book.title
        ctx["title"]=f"Page not found - {book_title}" if book_title else "Page not found"
        ctx["path"]=input_name; ctx["content"]=content_html; ctx["path_to_root"]=""
        ctx.pop("chapter_title",None); ctx.pop("section",None); ctx.pop("git_repository_edit_url",None)
        site=html.site_url_or_default()
        if site: ctx["base_url"]=site
        try: rendered=self.engine.render("index",ctx,state_extra={"current_chapter_index":None})
        except TemplateError as e: raise e.to_md_error()
        write_file(path_join(self.dest,output_name),rendered.encode('utf-8'))
    def render_print(self,base,flat):
        html=self.html
        id_counts={}
        parts=[]; first=True
        for ch in flat:
            if not ch.get("path"): continue
            renderer=MarkdownRenderer(html,chapter_path=ch["path"],print_mode=True,id_counts=id_counts)
            content_html=renderer.render(ch.get("content",""))
            if not first and html.print_page_break:
                parts.append('<div style="break-before: page; page-break-before: always;"></div>')
            parts.append(content_html); first=False
        ctx=dict(base)
        ctx["title"]=self.cfg.book.title or ""
        ctx["path"]="print.md"; ctx["content"]="".join(parts); ctx["path_to_root"]=""; ctx["is_print"]=True
        ctx.pop("chapter_title",None); ctx.pop("section",None); ctx.pop("git_repository_edit_url",None)
        try: rendered=self.engine.render("index",ctx,state_extra={"current_chapter_index":None})
        except TemplateError as e: raise e.to_md_error()
        write_file(path_join(self.dest,"print.html"),rendered.encode('utf-8'))
    def prepare_redirects(self):
        redirect=self.html.redirect
        if not redirect: return []
        existing=set()
        for ch in iter_chapters(self.book):
            if ch.get("path"): existing.add(html_url_path(ch["path"]))
        # group by page (key before #), preserving first-seen order
        groups={}; order=[]
        for src,dst in redirect.items():
            if "#" in src: page,frag=src.split("#",1); frag="#"+frag
            else: page,frag=src,None
            if page not in groups: groups[page]={"base":None,"base_key":None,"frag":{}}; order.append(page)
            if frag is None: groups[page]["base"]=dst; groups[page]["base_key"]=src
            else: groups[page]["frag"][frag]=dst
        files=[]
        for page in order:
            g=groups[page]
            norm=page.lstrip("/")
            frag_map=json.dumps(g["frag"],ensure_ascii=False,separators=(",",":"),sort_keys=True) if g["frag"] else "{}"
            if norm in existing:
                if g["base"] is not None:
                    raise MdError("Rendering failed",[f"redirect found for existing chapter at `{g['base_key']}`\nEither delete the redirect or remove the chapter."])
                self.fragment_maps[norm]=frag_map
            else:
                if g["base"] is None:
                    raise MdError("Rendering failed",["Unable to emit redirects",f"redirect entry for `{norm}` only has source paths with `#` fragments\nThere must be an entry without the `#` fragment to determine the default destination."])
                files.append((norm,g["base"],frag_map))
        return files
    def emit_redirect_files(self,files):
        for norm,url,frag_map in files:
            if norm=="": continue
            ctx={"url":url,"fragment_map":frag_map}
            try: rendered=self.engine.render("redirect",ctx)
            except TemplateError as e: raise e.to_md_error()
            except Exception:
                # redirect ctx has no chapters etc; helpers needing them fail upstream in various ways; re-raise template errors only
                raise
