    def copy_source_files(self):
        src_dir=self.cfg.source_dir(); dest=self.dest
        try: dest_real=os.path.realpath(dest)
        except Exception: dest_real=dest
        if not os.path.isdir(src_dir): return
        for dirpath,dirnames,filenames in os.walk(src_dir,followlinks=True):
            # avoid destination subtree
            # prune dirs that are destination
            pruned=[]
            for d in list(dirnames):
                full=os.path.join(dirpath,d)
                try:
                    if os.path.realpath(full)==dest_real:
                        pruned.append(d)
                except Exception: pass
            for d in pruned: dirnames.remove(d)
            for fn in filenames:
                if fn.rsplit(".",1)[-1]=="md" if "." in fn else False:
                    continue
                full=os.path.join(dirpath,fn)
                try:
                    if os.path.realpath(full).startswith(dest_real+os.sep): continue
                except Exception: pass
                rel=os.path.relpath(full,src_dir)
                out=os.path.join(dest,rel)
                try:
                    os.makedirs(os.path.dirname(out),exist_ok=True) if os.path.dirname(out) else None
                    # copy following symlinks (shutil.copy follows)
                    shutil.copyfile(full,out)
                except OSError as e:
                    raise MdError("Rendering failed",[os_error_str(e)])

def write_file(path,data):
    parent=os.path.dirname(path)
    if parent: os.makedirs(parent,exist_ok=True)
    with open(path,'wb') as f: f.write(data)
