            render_custom(name,processed,cfg,book_obj.root,dest)

def render_markdown(book,dest):
    if os.path.lexists(dest):
        try:
            if os.path.isdir(dest) and not os.path.islink(dest): shutil.rmtree(dest)
            elif os.path.islink(dest): os.unlink(dest)
            else: raise NotADirectoryError(20,os.strerror(20))
        except OSError as e:
            raise MdError("Rendering failed",["Unable to remove stale Markdown output",os_error_str(e)])
    os.makedirs(dest,exist_ok=True)
    from .book import iter_chapters
    for ch in iter_chapters(book):
        if not ch.get("path"): continue
        out=path_join(dest,ch["path"])
        write_file(out,(ch.get("content","") or "").encode('utf-8'))

def render_custom(name,book,cfg,root,dest):
    out_table=cfg.output_table()
    conf=out_table.get(name,{})
    cmdstr=conf.get("command") if isinstance(conf,dict) else None
    if not isinstance(cmdstr,str): cmdstr=f"mdbook-{name}"
    optional=bool(conf.get("optional")) if isinstance(conf,dict) else False
    log.info("mdbook_driver::builtin_renderers",f'Invoking the "{name}" renderer')
    try:
        parts=shell_split(cmdstr)
    except Exception:
        parts=[]
    if not parts:
        raise MdError("Rendering failed",["Command string was empty"])
    # create dest and run with cwd=dest
    try:
        os.makedirs(dest,exist_ok=True)
    except OSError as e:
        raise MdError("Rendering failed",["Unable to start the backend",os_error_str(e)])
    ctx={"version":VERSION,"root":root,"book":book_to_json(book),"config":cfg.serialize(),"destination":dest}
    payload=json.dumps(ctx,ensure_ascii=False,separators=(",",":"))
    try:
        proc=subprocess.run(parts,input=payload.encode('utf-8'),cwd=dest)
    except FileNotFoundError as e:
        if optional:
            log.warn("mdbook_driver::builtin_renderers",f"The command `{cmdstr}` for backend `{name}` was not found, but was marked as optional.")
            return
        log.error("mdbook_driver::builtin_renderers",f'The command `{cmdstr}` wasn\'t found, is the "{name}" backend installed? If you want to ignore this error when the "{name}" backend is not installed, set `optional = true` in the `[output.{name}]` section of the book.toml configuration file.')
        raise MdError("Rendering failed",["Unable to start the backend",os_error_str(e)])
    except OSError as e:
        raise MdError("Rendering failed",["Unable to start the backend",os_error_str(e)])
    if proc.returncode!=0:
        log.error("mdbook_driver::builtin_renderers","Renderer exited with non-zero return code.")
        raise MdError("Rendering failed",[f'The "{name}" renderer failed'])

def load_and_build(root,dest_override=None,live_reload=None):
    book=MDBook.load(root)
    book.dest_override=dest_override
    if live_reload: book.live_reload_endpoint=live_reload
    build_book(book)
    return book
