MIME_EXTRA={".md":"text/markdown",".svg":"image/svg+xml",".woff2":"font/woff2",".woff":"font/woff",".ttf":"font/ttf",".eot":"application/vnd.ms-fontobject",".js":"text/javascript",".mjs":"text/javascript",".json":"application/json",".toml":"text/plain",".txt":"text/plain",".rs":"text/plain",".png":"image/png",".jpg":"image/jpeg",".jpeg":"image/jpeg",".gif":"image/gif",".ico":"image/x-icon",".css":"text/css",".html":"text/html",".htm":"text/html",".xml":"text/xml",".pdf":"application/pdf",".wasm":"application/wasm"}

def mime_for(path):
    ext=os.path.splitext(path)[1].lower()
    if ext in MIME_EXTRA: return MIME_EXTRA[ext]
    t,_=mimetypes.guess_type(path)
