# ---------------- file watcher (poll) ----------------
class Watcher:
    def __init__(self,root,cfg,dest_abs=None):
        self.root=root; self.cfg=cfg; self.dest_abs=dest_abs
        self.snapshot={}
        self.ignore_patterns=[]
        self._load_gitignore()
        self.paths=self._watch_paths()
        self.snapshot=self._scan()
    def _load_gitignore(self):
        p=path_join(self.root,".gitignore")
        pats=[]
        if os.path.isfile(p):
            try:
                for line in open(p,encoding='utf-8',errors='ignore'):
                    line=line.strip()
                    if not line or line.startswith("#"): continue
                    pats.append(line)
            except Exception: pass
        self.ignore_patterns=pats
    def _ignored(self,full):
        try: rel=os.path.relpath(full,self.root)
        except Exception: return False
        if rel.startswith(".."): return False
        rel=rel.replace(os.sep,"/")
        for pat in self.ignore_patterns:
            neg=False
            if pat.startswith("!"): neg=True; pat=pat[1:]
            pat=pat.lstrip("/")
            matched=gitignore_match(pat,rel)
            if matched and not neg: return True
            if matched and neg: return False
        return False
    def _watch_paths(self):
        cfg=self.cfg; paths=[]
        src=cfg.source_dir(); paths.append(src)
        paths.append(path_join(self.root,"book.toml"))
        # theme dir(s)
        try: html=cfg.html_config()
        except Exception: html=None
