class Handler(socketserver.BaseRequestHandler):
    state=None
    def handle(self):
        conn=self.request
        try:
            f=conn.makefile('rb')
            while True:
                line=f.readline(65536)
                if not line: break
                if line in (b'\r\n',b'\n'): continue
                try: req=line.decode('iso-8859-1').rstrip("\r\n")
                except Exception: break
                parts=req.split(" ")
                if len(parts)<2: break
                method,raw_path=parts[0],parts[1]
                headers={}
                while True:
                    hline=f.readline(65536)
                    if not hline or hline in (b'\r\n',b'\n'): break
                    hs=hline.decode('iso-8859-1').rstrip("\r\n")
                    if ":" in hs:
