                # read body if any
                clen=int(headers.get('content-length','0') or 0)
                if clen>0:
                    f.read(clen)
                keep=self.handle_request(conn,method,raw_path,headers)
                if not keep: break
        except (BrokenPipeError,ConnectionResetError):
            pass
        except Exception:
            pass
        finally:
            try: conn.close()
            except Exception: pass
    def respond(self,conn,status,reason,headers,body=b"",head_only=False):
        hdrs="".join(f"{k}: {v}\r\n" for k,v in headers)
        resp=f"HTTP/1.1 {status} {reason}\r\n{hdrs}date: {format_http_date()}\r\n\r\n".encode('iso-8859-1')
        conn.sendall(resp)
        if body and not head_only:
            conn.sendall(body)
    def handle_request(self,conn,method,raw_path,headers):
        state=self.state
        from urllib.parse import unquote,urlsplit
        split=urlsplit(raw_path)
        path=unquote(split.path)
