        if path=="/__livereload":
            if method not in ("GET","HEAD"):
                self.respond(conn,405,"Method Not Allowed",[("allow","GET,HEAD"),("content-length","0")]); return True
            return self.handle_ws(conn,headers)
        if method not in ("GET","HEAD"):
            self.respond(conn,405,"Method Not Allowed",[("allow","GET,HEAD"),("content-length","0")]); return True
        head_only=(method=="HEAD")
        # root -> index.html
        if path in ("","/"):
            rel="index.html"
        else:
            # normalize dot segments like browsers/warp fs path cleaning but prevent escaping
            rel=normalize_url_path(path)
            if rel is None:
                return self.serve_fallback(conn,headers,head_only)
        fpath=os.path.join(state.build_dir,*rel.split("/")) if rel else state.build_dir
        if os.path.isfile(fpath):
            return self.serve_file(conn,fpath,200,"OK",headers,head_only)
        return self.serve_fallback(conn,headers,head_only)
