        fb=self.state.fallback_file
        if fb and os.path.isfile(fb):
            return self.serve_file(conn,fb,404,"Not Found",headers,head_only)
        self.respond(conn,404,"Not Found",[("content-length","0")],b"",head_only)
        return True
