            if parsed is None:
                hdrs=[("content-type",ctype),("accept-ranges","bytes"),("last-modified",lastmod),("content-range",f"bytes */{size}"),("content-length","0")]
                self.respond(conn,416,"Range Not Satisfiable",hdrs,b"",head_only); return True
