            self.respond(conn,206,"Partial Content",hdrs,body,head_only); return True
        try:
            with open(fpath,'rb') as f: body=f.read()
        except OSError:
            self.respond(conn,404,"Not Found",[("content-length","0")]); return True
        hdrs=[("content-type",ctype),("accept-ranges","bytes"),("last-modified",lastmod),("content-length",str(len(body)))]
        self.respond(conn,status,reason,hdrs,body,head_only); return True
