        conn_hdr=headers.get('connection','').lower()
        if 'upgrade' not in conn_hdr:
            body=b"Connection header did not include 'upgrade'"
            self.respond(conn,400,"Bad Request",[("content-type","text/plain; charset=utf-8"),("content-length",str(len(body)))],body); return True
        if headers.get('upgrade','').lower()!='websocket':
