            self.respond(conn,400,"Bad Request",[("content-type","text/plain; charset=utf-8"),("content-length",str(len(body)))],body); return True
        key=headers.get('sec-websocket-key')
        if not key or headers.get('sec-websocket-version')!='13':
            body=b"Sec-WebSocket-Version must be 13" if headers.get('sec-websocket-version')!='13' else b"Sec-WebSocket-Key header missing"
            self.respond(conn,400,"Bad Request",[("content-type","text/plain; charset=utf-8"),("content-length",str(len(body)))],body); return True
        accept=base64.b64encode(hashlib.sha1((key+"258EAFA5-E914-47DA-95CA-C5AB0DC85B11").encode()).digest()).decode()
        resp=(f"HTTP/1.1 101 Switching Protocols\r\nconnection: upgrade\r\nupgrade: websocket\r\nsec-websocket-accept: {accept}\r\ndate: {format_http_date()}\r\n\r\n").encode()
        conn.sendall(resp)
