        return False

def read_ws_frame(conn,buf):
    while len(buf)<2:
        d=conn.recv(4096)
        if not d: return None,buf
        buf+=d
    b0,b1=buf[0],buf[1]; fin=b0>>7; op=b0&15; ln=b1&127; idx=2
    if ln==126:
        while len(buf)<4: buf+=conn.recv(4096)
        ln=struct.unpack('>H',buf[2:4])[0]; idx=4
    elif ln==127:
        while len(buf)<10: buf+=conn.recv(4096)
        ln=struct.unpack('>Q',buf[2:10])[0]; idx=10
    mask=None
    if b1&128:
        while len(buf)<idx+4: buf+=conn.recv(4096)
        mask=buf[idx:idx+4]; idx+=4
    while len(buf)<idx+ln:
        d=conn.recv(4096)
        if not d: return None,buf
        buf+=d
    payload=buf[idx:idx+ln]; buf=buf[idx+ln:]
    if mask: payload=bytes(x^mask[i%4] for i,x in enumerate(payload))
    return (fin,op,payload),buf

def normalize_url_path(path):
    # returns rel path without leading slash, resolving . and ..; None if escapes
    parts=[]
    for seg in path.split("/"):
        if seg in ("","."): continue
        if seg=="..":
            if parts: parts.pop()
            else: return None
        else: parts.append(seg)
    return "/".join(parts)

def parse_range(hdr,size):
    # bytes=start-end / start- / -suffix
    m=re.match(r'^bytes=(.+)$',hdr.strip())
    if not m: return None
    spec=m.group(1)
    if "," in spec: return "multipart"
    if "-" not in spec: return None
    a,b=spec.split("-",1); a=a.strip(); b=b.strip()
    try:
        if a=="" :
            suffix=int(b)
            if suffix<=0: return None
            start=max(0,size-suffix); end=size-1
        else:
            start=int(a); end=int(b) if b!="" else size-1
    except Exception: return None
    if start>=size or start>end or end<0: return None
    end=min(end,size-1)
    return start,end

