def parse_range(hdr,size):
    # bytes=start-end / start- / -suffix
    m=re.match(r'^bytes=(.+)$',hdr.strip())
    if not m: return None
    spec=m.group(1)
    if "," in spec: return "multipart"
    if "-" not in spec: return None
    a,b=spec.split("-",1); a=a.strip(); b=b.strip()
    try:
        if a=="" :
            suffix=int(b)
            if suffix<=0: return None
            start=max(0,size-suffix); end=size-1
        else:
            start=int(a); end=int(b) if b!="" else size-1
    except Exception: return None
    if start>=size or start>end or end<0: return None
    end=min(end,size-1)
    return start,end

