        if s: self.cur.append(s)
    def flush_normal(self):
        if self.cur:
            txt="".join(self.cur)
            self.pieces.append((False,txt)); self.cur=[]
    def add_code(self,s):
        self.flush_normal(); self.pieces.append((True,s))
    def finish(self):
        self.flush_normal()
        out=[]
        for is_code,txt in self.pieces:
            if is_code:
                t=txt.strip("\n")
                if t.strip()=="": continue
                out.append(t)
            else:
                t=" ".join(txt.split())
                if t: out.append(t)
        return " ".join(out).strip()
    def inline(self,text):
