        nodes=InlineParser(text,self.state.refs if self.state else {}, self.state.footnotes if self.state else {}).parse()
        self.inline_nodes(nodes)
        return nodes
    def inline_nodes(self,nodes):
        for nd in nodes:
            k=nd.kind
            if k=="text": self.add_text(nd.text)
            elif k=="code": self.add_text(nd.text)
            elif k in ("softbreak","hardbreak"): self.add_text(" ")
            elif k=="html": continue
            elif k=="footnote_ref":
                key=__import__('app.markdown',fromlist=['normalize_label']).normalize_label(nd.label)
                if self.state and key in self.state.footnotes:
                    if key not in self.footnote_nums:
                        self.footnote_order.append(key); self.footnote_nums[key]=len(self.footnote_order)
                    self.add_text(f"[{self.footnote_nums[key]}]")
                else:
                    self.add_text(f"[^{nd.label}]")
            elif k in ("em","strong","del","link","image"):
                self.add_space(); self.inline_nodes(nd.children); self.add_space()
            else:
                self.inline_nodes(nd.children)
    def block(self,b):
        k=b.kind
        if k in ("paragraph","heading"):
            self.inline(b.text); self.add_space()
        elif k=="code":
            self.add_code(b.text)
