            docs.append({"id_url":cur_url,"title":cur_title,"breadcrumbs":" » ".join(breadcrumbs_base+[cur_title]),"body":sb.finish()})
        else:
            docs.append({"id_url":url,"title":ch["name"],"breadcrumbs":" » ".join(breadcrumbs_base+[ch["name"]]),"body":sb.finish()})
    return docs

